package dev.industrialtechnology.expansion;
import cpw.mods.fml.common.network.simpleimpl.*;import io.netty.buffer.ByteBuf;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.init.Items;import net.minecraft.item.ItemStack;import dev.industrialtechnology.core.ServerWork;import dev.industrialtechnology.railway.*;import net.minecraftforge.common.ForgeHooks;
public final class ExpansionCommand implements IMessage {private int window,entity,action,value;public ExpansionCommand(){}public ExpansionCommand(int w,int e,int a,int v){window=w;entity=e;action=a;value=v;}public void toBytes(ByteBuf b){b.writeInt(window);b.writeInt(entity);b.writeByte(action);b.writeByte(value);}public void fromBytes(ByteBuf b){window=b.readInt();entity=b.readInt();action=b.readUnsignedByte();value=b.readUnsignedByte();}public static final class Handler implements IMessageHandler<ExpansionCommand,IMessage>{public IMessage onMessage(final ExpansionCommand m,MessageContext c){final EntityPlayerMP p=c.getServerHandler().playerEntity;ServerWork.enqueue(()->apply(p,m));return null;}}
 public static void apply(EntityPlayerMP p,ExpansionCommand m){if(m.action<=5){if(!(p.ridingEntity instanceof EntityRollingStock))return;EntityRollingStock e=(EntityRollingStock)p.ridingEntity;if(e.getEntityId()!=m.entity)return;long now=p.worldObj.getTotalWorldTime();if(!RailControls.allow(p,now))return;if(m.action==5){if(e.permitted(p))p.openGui(dev.industrialtechnology.core.IndustrialTechnology.instance,4,p.worldObj,e.getEntityId(),0,0);}else e.control(p,m.action);return;}if(!(p.openContainer instanceof ExpansionContainer))return;ExpansionContainer c=(ExpansionContainer)p.openContainer;if(c.windowId!=m.window||!c.canInteractWith(p)||!ForgeHooks.canInteractWith(p,c)||!c.actionAllowed(p))return;if(m.action>=10&&m.action<13)c.logicalClick(p,m.action-10,(m.value&1)!=0,(m.value&2)!=0);else if(m.action==20&&c.train!=null&&c.train.stock==StockType.STEAM){ItemStack held=p.inventory.getItemStack();if(held!=null&&held.getItem()==Items.water_bucket&&held.stackSize==1&&c.train.water<=29000){c.train.water+=1000;p.inventory.setItemStack(new ItemStack(Items.bucket));p.updateHeldItem();}}else if(m.action==21&&c.train!=null&&c.train.stock.engine()&&c.train.riddenByEntity==null){p.mountEntity(c.train);p.closeScreen();}c.send(p);}
 private static final class RailControls {private static final java.util.WeakHashMap<EntityPlayerMP,long[]> used=new java.util.WeakHashMap<>();static boolean allow(EntityPlayerMP p,long now){long[] n=used.get(p);if(n==null||n[0]!=now){n=new long[]{now,0};used.put(p,n);}return ++n[1]<=4;}}
}
